"""Independent, deliberately naive replay reference (for differential testing)."""

def ref_replay(req):
    caps = req['capacities']
    flows = {}
    for f in req['flows']:
        flows[f['id']] = f
    tables = {}
    enabled = set()
    results = []
    for ev in req['events']:
        op = ev['op']
        if op == 'put':
            f = flows[ev['flow']]
            node = ev['node']
            lab = f['labels'][f['path'].index(node)]
            key = (node, lab)
            if tables.get(key) == f['id']:
                results.append({'status': 'ok'})
            elif key in tables and tables[key] in enabled:
                results.append({'status': 'busy'})
            elif key not in tables and len([1 for (n, l) in tables if n == node]) >= caps[node]:
                results.append({'status': 'full'})
            else:
                tables[key] = f['id']
                results.append({'status': 'ok'})
        elif op == 'enable':
            f = flows[ev['flow']]
            good = True
            for i, n in enumerate(f['path']):
                if tables.get((n, f['labels'][i])) != f['id']:
                    good = False
            if good:
                enabled.add(f['id'])
                results.append({'status': 'ok'})
            else:
                results.append({'status': 'unready'})
        elif op == 'disable':
            enabled.discard(ev['flow'])
            results.append({'status': 'ok'})
        elif op == 'reset':
            enabled.clear()
            results.append({'status': 'ok'})
        elif op == 'packet':
            f = flows[ev['flow']]
            h = bytes.fromhex(ev['header'])
            pl = bytes.fromhex(ev['payload'])
            kinds = f['kinds']
            tpl = bytes.fromhex(f['template'])
            N = len(f['path'])
            if f['id'] not in enabled:
                mode, reason = 'ip', 'disabled'
            elif any(h[i] != tpl[i] for i, c in enumerate(kinds) if c == 'K'):
                mode, reason = 'ip', 'mismatch'
            elif h[kinds.index('Q')] > 7:
                mode, reason = 'ip', 'qos'
            else:
                mode, reason = 'mpls', 'compressed'
            t = h[kinds.index('T')]
            res = bytes(h[i] for i, c in enumerate(kinds) if c == 'D')
            q = h[kinds.index('Q')]
            wire = []
            for i in range(N):
                if t <= i:
                    break
                if mode == 'mpls':
                    val = (f['labels'][i] << 12) | (q << 9) | (1 << 8) | (t - i)
                    wire.append((val.to_bytes(4, 'big') + res + pl).hex())
                else:
                    hh = bytearray(h)
                    hh[kinds.index('T')] = t - i
                    wire.append((bytes(hh) + pl).hex())
            if len(wire) == N:
                if mode == 'mpls':
                    out = bytearray(tpl)
                    di = 0
                    for i, c in enumerate(kinds):
                        if c == 'D':
                            out[i] = res[di]
                            di += 1
                        elif c == 'Z':
                            out[i] = 0
                        elif c == 'Q':
                            out[i] = q
                        elif c == 'T':
                            out[i] = t - (N - 1)
                    delivered = (bytes(out) + pl).hex()
                else:
                    delivered = wire[-1]
            else:
                delivered = None
            results.append({'mode': mode, 'reason': reason, 'wire': wire,
                            'delivered': delivered,
                            'byte_hops': sum(len(bytes.fromhex(w)) for w in wire)})
        else:
            raise AssertionError('bad op')
    return {'results': results, 'active': sorted(enabled),
            'tables': [{'node': n, 'label': l, 'flow': fl}
                       for (n, l), fl in sorted(tables.items())]}
